            for k in range(_sage_const_0 , m+_sage_const_1 ):
                rhs = rhs + math.comb(m,k) * np.linalg.matrix_power(X,k) @ Y @ np.linalg.matrix_power(-X, m-k)
            rep.close(lhs, rhs, f"n={n} t={trial} m={m}")
